From d6aa2e2716d2d607d4bdb91c86a15140d6f8ed4d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:49:48 +0100
Subject: [PATCH] kded: give the vault dialogs their own app id

The vault dialogs are windows of kded, so on Wayland they got its app id
and the task manager grouped them as "KDED" with its icon. Show them with
a Vaults app id and install a matching hidden desktop file for it.

BUG: 418011
---
 kded/CMakeLists.txt              |  1 +
 kded/org.kde.plasmavault.desktop |  8 ++++++++
 kded/service.cpp                 | 18 ++++++++++++++----
 3 files changed, 23 insertions(+), 4 deletions(-)
 create mode 100644 kded/org.kde.plasmavault.desktop

diff --git a/kded/CMakeLists.txt b/kded/CMakeLists.txt
index aa9c702..b13dac8 100644
--- a/kded/CMakeLists.txt
+++ b/kded/CMakeLists.txt
@@ -107,3 +107,4 @@ if (HAVE_NETWORKMANAGER)
 endif()

 install(TARGETS kded_plasmavault DESTINATION ${KDE_INSTALL_PLUGINDIR}/kf6/kded)
+install(FILES org.kde.plasmavault.desktop DESTINATION ${KDE_INSTALL_APPDIR})
diff --git a/kded/org.kde.plasmavault.desktop b/kded/org.kde.plasmavault.desktop
new file mode 100644
index 0000000..0c9f80f
--- /dev/null
+++ b/kded/org.kde.plasmavault.desktop
@@ -0,0 +1,8 @@
+[Desktop Entry]
+# Never shown in a menu, hence no Exec: it gives the vault dialogs,
+# which live in kded, their own name and icon on Wayland
+Name=Vaults
+Type=Application
+Icon=plasmavault
+NoDisplay=true
+StartupNotify=false
diff --git a/kded/service.cpp b/kded/service.cpp
index ea44606..8139776 100644
--- a/kded/service.cpp
+++ b/kded/service.cpp
@@ -8,6 +8,7 @@

 #include <QDBusObjectPath>
 #include <QFile>
+#include <QGuiApplication>
 #include <QMessageBox>
 #include <QProcess>
 #include <QSocketNotifier>
@@ -179,13 +180,22 @@ PlasmaVault::VaultInfoList PlasmaVaultService::availableDevices() const
     return result;
 }

+static void showVaultDialog(QDialog *dialog, void (QDialog::*show)() = &QDialog::show)
+{
+    // The dialogs live in kded, so give them our own app id instead of kded's
+    const auto desktopFileName = QGuiApplication::desktopFileName();
+    QGuiApplication::setDesktopFileName(QStringLiteral("org.kde.plasmavault"));
+    (dialog->*show)();
+    QGuiApplication::setDesktopFileName(desktopFileName);
+}
+
 void PlasmaVaultService::requestNewVault()
 {
     const auto dialog = new VaultCreationWizard();

     connect(dialog, &VaultCreationWizard::createdVault, this, &PlasmaVaultService::registerVault);

-    dialog->show();
+    showVaultDialog(dialog);
 }

 void PlasmaVaultService::requestImportVault()
@@ -194,7 +204,7 @@ void PlasmaVaultService::requestImportVault()

     connect(dialog, &VaultImportingWizard::importedVault, this, &PlasmaVaultService::registerVault);

-    dialog->show();
+    showVaultDialog(dialog);
 }

 void PlasmaVaultService::slotRegistered(const QDBusObjectPath &path)
@@ -320,7 +330,7 @@ void showPasswordMountDialog(Vault *vault, OnAccepted onAccepted, OnRejected onR
     QObject::connect(dialog, &QDialog::accepted, vault, onAccepted);
     QObject::connect(dialog, &QDialog::rejected, vault, onRejected);

-    dialog->open();
+    showVaultDialog(dialog, &QDialog::open);
 }
 //^

@@ -386,7 +396,7 @@ void PlasmaVaultService::configureVault(const QString &device)
     if (auto vault = d->vaultFor(device)) {
         const auto dialog = new VaultConfigurationDialog(vault);

-        dialog->show();
+        showVaultDialog(dialog);
     }
 }

